    input [99:0] in,
    output [99:0] out_both,
    output [99:0] out_any,
    output [99:0] out_different
);
    wire [99:0] reg_both;
    wire [99:0] reg_any;
    wire [99:0] reg_different;
    reg [99:0] reg_reg_both;
    reg [99:0] reg_reg_any;
    reg [99:0] reg_reg_different;
    always @(*) begin
        reg_both[0] = in[0] & in[99];
        reg_both[99] = in[99] & in[0];
        for (int i = 1; i < 99; i = i + 1)
            reg_both[i] = in[i] & in[i-1];
        reg_any[0] = in[0] | in[99];
        reg_any[99] = in[99] | in[0];
        for (int i = 1; i < 99; i = i + 1)
