// Any neighbour: (a | b | c)
// Different neighbour: a ^ b
module TopModule (
    input [99:0] in,
    output [99:0] out_both,
    output [99:0] out_any,
    output [99:0] out_different
);
    genvar i;
    generate
        for (i = 0; i < 100; i = i + 1) begin
            wire a = in[i];
            wire b = in[(i + 99) % 100]; // neighbour to the left
            wire c = in[(i + 1) % 100]; // neighbour to the right
            assign out_both[i] = (a & b) | (a & c) | (b & c);
            assign out_any[i] = a | b | c;
            assign out_different[i] = a ^ b;
        end
    endgenerate
endmodule

