  generate
    for (i = 0; i < 100; i = i + 1) begin : each_bit
      wire left = (i == 0) ? in[99] : in[i-1];
      wire right = (i == 99) ? in[0] : in[i+1];
      wire both = in[i] & left;
      wire any = in[i] | right;
      wire different = in[i] ^ left;
      assign out_both[i] = both;
      assign out_any[i] = any;
      assign out_different[i] = different;
    end
  endgenerate
endmodule

