// One-bit wide multiplexer with 3 inputs. Selects one of the 3 inputs
// based on the select input.
module mux_1bit(input [2:0] in, input [0:0] select, output reg out);
    always @(*) begin
        case (select)
            0: out = in[0];
            1: out = in[1];
            2: out = in[2];
        endcase
    end
endmodule

